package net.officefloor.hq.app.voidreason;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's list of void reasons. While the list is not empty, a claim is voided only with a reason chosen from
 * it.
 */
@Service
public class VoidReasonService {

    private final VoidReasonRepository reasons;
    private final SheetService sheets;
    private final Audit audit;

    public VoidReasonService(VoidReasonRepository reasons, SheetService sheets, Audit audit) {
        this.reasons = reasons;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's void reasons, in the order they were added. */
    @Transactional(readOnly = true)
    public List<VoidReason> list(String sheetId) {
        return reasons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Adds a reason, trimmed, to the sheet's list; refused when blank or already on the list. */
    @Transactional
    public VoidReason add(String by, String sheetId, String reason) {
        String text = reason == null ? "" : reason.trim();
        if (text.isEmpty()) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Enter a void reason.");
        }
        sheets.lock(sheetId);
        if (reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, text + " is already a void reason.");
        }
        VoidReason added = reasons.saveAndFlush(new VoidReason(sheetId, text));
        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + by + " reason=" + text);
        return added;
    }

    /**
     * The reason a claim is voided with: null when none is given and the list is empty. Refused when the list is not
     * empty and the reason is missing or not on it, or when a reason is given that is not on the list.
     */
    @Transactional(readOnly = true)
    public String refuseUnlessListed(String sheetId, String reason) {
        String text = reason == null ? "" : reason.trim();
        if (text.isEmpty()) {
            if (reasons.existsBySheetId(sheetId)) {
                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                        "Choose a reason to void this claim.");
            }
            return null;
        }
        if (!reasons.existsBySheetIdAndReason(sheetId, text)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, text + " is not a void reason.");
        }
        return text;
    }
}
-- The sheet's void reasons, each at most once: while it has any, a claim is voided only with one of them.
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(140) NOT NULL
);
CREATE UNIQUE INDEX void_reason_once ON void_reason (sheet_id, reason);

-- The reason a claim was voided with; null for one not voided, or voided without one.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(140);
-- The sheet's claim templates, each name at most once: a name, an amount and a note a claim can be added from.
-- A claim made from one copies its amount and note, so a later change to the template leaves it as it was.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    name     VARCHAR(140)   NOT NULL,
    amount   DECIMAL(14, 2) NOT NULL CHECK (amount >= 0),
    note     VARCHAR(500)   NOT NULL DEFAULT ''
);
CREATE UNIQUE INDEX claim_template_name ON claim_template (sheet_id, name);
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, Injectable, effect, inject, signal, untracked } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface VoidReasonView {
  id: number;
  reason: string;
}

// The void reasons of the active sheet, in the order they were added. While there are any, a claim is voided only
// with one chosen from them.
@Injectable({ providedIn: 'root' })
export class VoidReasonStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly list = signal<readonly VoidReasonView[]>([]);

  /** Re-read the sheet's void reasons from the store. */
  async load(sheet: string): Promise<void> {
    this.list.set([]);
    const l = await firstValueFrom(
      this.http.get<VoidReasonView[]>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`),
    );
    if (this.session.sheetId() === sheet) this.list.set(l);
  }

  async add(sheet: string, reason: string): Promise<void> {
    const r = await firstValueFrom(
      this.http.post<VoidReasonView>(`/api/sheets/${encodeURIComponent(sheet)}/void-reasons`, { reason }),
    );
    if (this.session.sheetId() === sheet) this.list.update((l) => [...l, r]);
  }
}

// The active sheet's list of void reasons. A blank reason, or one already on the list, is refused.
@Component({
  selector: 'app-void-reasons',
  template: `
    <section aria-label="Void reasons">
      <h2>Void reasons</h2>
      <form (submit)="add($event)" aria-label="Add a void reason">
        <label for="void-reason-text">Void reason</label>
        <input
          id="void-reason-text"
          data-testid="void-reason-text"
          [value]="text()"
          (input)="text.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="void-reason-add">Add void reason</button>
        @if (error(); as err) {
          <p role="alert" data-testid="void-reason-error">{{ err }}</p>
        }
      </form>

      <ul aria-label="Void reasons on the sheet">
        @for (r of store.list(); track r.id) {
          <li [attr.data-testid]="'void-reason-row-' + r.reason">{{ r.reason }}</li>
        }
      </ul>
    </section>
  `,
})
export class VoidReasons {
  private readonly session = inject(Session);
  protected readonly store = inject(VoidReasonStore);

  protected readonly text = signal('');
  protected readonly error = signal<string | null>(null);
  // A submit in flight: a second one before it answers is ignored.
  private submitting = false;

  constructor() {
    // Re-read the void reasons from the store each time a sheet is loaded.
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.error.set(null);
        this.store.list.set([]);
        if (id) this.store.load(id).catch(() => this.error.set('Could not load the void reasons.'));
      });
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async add(e: Event): Promise<void> {
    e.preventDefault();
    if (this.submitting) return;
    this.error.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const reason = this.text().trim();
    if (!reason) {
      this.error.set('Enter a void reason.');
      return;
    }
    if (this.store.list().some((r) => r.reason === reason)) {
      this.error.set(`${reason} is already a void reason.`);
      return;
    }
    this.submitting = true;
    try {
      await this.store.add(sheet, reason);
    } catch (err) {
      this.error.set(
        err instanceof HttpErrorResponse && err.status === 409
          ? `${reason} is already a void reason.`
          : 'Could not add the void reason.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.asof.AsOfContext;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 *
 * A record of a change made by a user acting on behalf of another (see {@link OnBehalf}) ends with for=<that one>,
 * unless it only reports figures (ROLLUP, TOTALS, ALERT). A SNAPSHOT, written by a change of today the user makes,
 * carries it too.
 */
@Service
public class Audit {

    /** Tells for whom a user acts on a sheet, when they act on another's behalf. */
    public interface OnBehalf {
        Optional<String> forOf(String sheetId, String user);
    }

    /** The records that only report figures, which never carry for=. */
    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");

    /** A record's event, sheet and user: its head. */
    private static final Pattern HEAD = Pattern.compile("^(\\S+) sheet=(\\S+) by=(.+?)(?= [a-z][a-z-]*=|$)");

    private final Path file;
    private final ObjectProvider<OnBehalf> onBehalf;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<OnBehalf> onBehalf) {
        this.file = Path.of(path);
        this.onBehalf = onBehalf;
    }

    /**
     * Append one audit record. Tests assert the exact line(s) in the file. A request answered as of a date changes
     * nothing, so it writes none.
     */
    public synchronized void record(String entry) {
        if (AsOfContext.active()) {
            return;
        }
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused (and
     * rolled back) writes nothing. Outside a transaction the record is appended at once.
     */
    public void recordOnCommit(String record) {
        String entry = record + onBehalfOf(record);
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** " for=<who>" when the record's user makes the change on another's behalf, as things stand now; else "". */
    private String onBehalfOf(String entry) {
        Matcher m = HEAD.matcher(entry);
        OnBehalf who = onBehalf.getIfAvailable();
        if (who == null || !m.find() || FIGURES_ONLY.contains(m.group(1))) {
            return "";
        }
        return who.forOf(m.group(2), m.group(3)).map(f -> " for=" + f).orElse("");
    }

    /** A field of a record: its key and value, the value running to the next field or the end. */
    private static final Pattern FIELD = Pattern.compile("(?<=^| )([a-z][a-z-]*)=(.*?)(?= [a-z][a-z-]*=|$)");

    /**
     * The records of a sheet exactly as the file holds them, newest first. With a name, only those about that person:
     * carrying name= or person= that name, compared as names are (case and surrounding spaces ignored).
     */
    public synchronized List<String> lines(String sheetId, String name) {
        if (!Files.exists(file)) {
            return List.of();
        }
        List<String> all;
        try {
            all = Files.readAllLines(file, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        String key = name == null ? "" : name.strip().toLowerCase(Locale.ROOT);
        List<String> found = new ArrayList<>();
        for (String line : all) {
            Matcher m = HEAD.matcher(line);
            if (m.find() && m.group(2).equals(sheetId) && (key.isEmpty() || about(line, key))) {
                found.add(line);
            }
        }
        Collections.reverse(found);
        return found;
    }

    /** Whether a record carries name= or person= the given name key. */
    private static boolean about(String line, String key) {
        Matcher f = FIELD.matcher(line);
        while (f.find()) {
            String k = f.group(1);
            if ((k.equals("name") || k.equals("person")) && f.group(2).strip().toLowerCase(Locale.ROOT).equals(key)) {
                return true;
            }
        }
        return false;
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

